from llguidance.gbnf_to_lark import GrammarParser, resolve, AlternativeNode, SequenceNode, RuleRefNode, LiteralNode, RepetitionNode
from pathlib import Path
import re

_WS_NAMES = {'ws', 'whitespace', 'space', 'opt_space', 'opt_ws'}
def to_class_name(n): return ''.join(p.capitalize() for p in re.split(r'[_\-]', n))

def semantic_name_for_seq(seq, parent_name, i):
    for node in seq.nodes:
        if isinstance(node, LiteralNode):
            val = node.value.strip()
            if val.isalpha():
                return f'{parent_name}{val.capitalize()}'
    for node in seq.nodes:
        if isinstance(node, RuleRefNode) and node.name not in _WS_NAMES:
            return f'{parent_name}{to_class_name(node.name)}'
    return f'{parent_name}Seq{i}'

for gbnf, test_rules in [
    ('json_ws.gbnf', ['value']),
    ('arithmetic.gbnf', ['term']),
    ('c.gbnf', ['statement', 'for_init']),
]:
    text = Path('resources/ground_truth/' + gbnf).read_text()
    p = GrammarParser(); rules = p.parse(text); resolve(rules)
    if 'start' in rules: rules['root'] = rules.pop('start'); rules['root'].name = 'root'
    print(f'=== {gbnf} ===')
    for rname in test_rules:
        rule = rules[rname]
        body = rule.alternatives
        cname = to_class_name(rname)
        if isinstance(body, AlternativeNode):
            for i, alt in enumerate(body.alternatives):
                if isinstance(alt, RuleRefNode):
                    print(f'  [{i}] RuleRef({alt.name}) -> {to_class_name(alt.name)}{cname}')
                elif isinstance(alt, SequenceNode):
                    print(f'  [{i}] Seq -> {semantic_name_for_seq(alt, cname, i)}')
    print()
